export type IconName = keyof typeof ICONS;

/** Every name in the set, in table order. */
export const ICON_NAMES = Object.keys(ICONS) as IconName[];

type Live = { id: string; key: string; s: Stroke; on: boolean; enter: boolean };
type State = { name: IconName; gen: number; live: Live[] };

const table = ICONS as Record<IconName, Record<string, Stroke>>;

/** Command letters and argument counts: `d` interpolates only when these match. */
const shape = (d: string) =>
  (d.match(/[a-zA-Z][^a-zA-Z]*/g) ?? []).map((c) => c[0] + ((c.slice(1).match(/-?[\d.]+(?:e-?\d+)?/g) ?? []).length)).join();

let morphD: boolean | undefined;
const canMorphD = () => (morphD ??= typeof CSS !== "undefined" && CSS.supports("d", 'path("M0 0")'));

function morphs(from: Stroke, to: Stroke) {
  if (Boolean(from.block) !== Boolean(to.block) || Boolean(from.cut) !== Boolean(to.cut)) return false;
  return from.d === to.d || (canMorphD() && shape(from.d) === shape(to.d));
}

function initial(name: IconName): State {
  return {
    name,
    gen: 0,
    live: Object.entries(table[name]).map(([key, s]) => ({ id: `${key}.0`, key, s, on: true, enter: false })),
  };
}

function next(prev: State, name: IconName): State {
  const want = table[name];
  const gen = prev.gen + 1;
  const taken = new Set<string>();
  const live: Live[] = [];
  for (const l of [...prev.live].sort((a, b) => Number(b.on) - Number(a.on))) {
    const s = want[l.key];
    if (s && !taken.has(l.key) && morphs(l.s, s)) {
      taken.add(l.key);
      live.push({ ...l, s, on: true, enter: !l.on });
    } else {
      live.push({ ...l, on: false, enter: false });
    }
  }
  for (const [key, s] of Object.entries(want)) {
    if (!taken.has(key)) live.push({ id: `${key}.${gen}`, key, s, on: true, enter: true });
  }
  const gone = live.filter((l) => !l.on);
  const drop = new Set(gone.slice(0, Math.max(0, gone.length - 8)).map((l) => l.id));
  return { name, gen, live: live.filter((l) => !drop.has(l.id)) };
}

const HIDE = 0.3;

// CSS `d` is set only after the first change; until then the attribute draws.
function dash(l: Live, morphing: boolean): CSSProperties | undefined {
  const f = l.s.f ?? 0;
  const t = l.s.t ?? 1;
  const len = t - f;
  const off = f === 0 ? len + HIDE : -(1 + HIDE);
  const style = {
    d: morphing ? `path("${l.s.d}")` : undefined,
    rotate: l.s.rot ? `${l.s.rot}deg` : undefined,
    "--len": len === 1 ? undefined : len,
    "--on": f === 0 ? undefined : -f,
    "--off": off === 1 + HIDE ? undefined : off,
  } as CSSProperties;
  return Object.values(style).some((v) => v !== undefined) ? style : undefined;
}

export type IconProps = Omit<ComponentProps<"svg">, "children"> & { name: IconName };

export function Icon({ name, className, ...props }: IconProps) {
  const [state, setState] = useState(() => initial(name));
  const mask = `icon-cut-${useId()}`;
  if (state.name !== name) setState(next(state, name));

  const cuts = state.live.filter((l) => l.s.cut);
  const path = (l: Live, extra?: string) => (
    <path
      key={l.id + (extra ?? "")}
      d={l.s.d}
      pathLength={1}
      className={[styles.stroke, l.s.block && styles.block, l.s.seam && styles.seam, l.s.fx && styles[l.s.fx], extra].filter(Boolean).join(" ")}
      data-off={l.on ? undefined : ""}
      data-enter={l.enter ? "" : undefined}
      style={dash(l, state.gen > 0)}
      onTransitionEnd={
        l.on || extra
          ? undefined
          : (e) => {
              if (e.propertyName === "stroke-dashoffset") {
                setState((s) => ({ ...s, live: s.live.filter((x) => x.id !== l.id || x.on) }));
              }
            }
      }
    />
  );

  return (
    // Size attributes keep it from drawing huge before CSS loads.
    <svg
      viewBox="0 0 16 16"
      width="16"
      height="16"
      aria-hidden="true"
      data-icon={name}
      data-ready={state.gen > 0 ? "" : undefined}
      className={className ? `${styles.icon} ${className}` : styles.icon}
      {...props}
    >
      {cuts.length > 0 && (
        <mask id={mask} maskUnits="userSpaceOnUse" x="0" y="0" width="16" height="16">
          <rect width="16" height="16" fill="white" stroke="none" />
          {cuts.map((l) => path(l, styles.cut))}
        </mask>
      )}
      <g mask={cuts.length > 0 ? `url(#${mask})` : undefined}>{state.live.filter((l) => !l.s.cut).map((l) => path(l))}</g>
      {cuts.map((l) => path(l))}
    </svg>
  );
}

@layer theme, base, components, utilities;

/* Shared text utilities; other components compose these classes. */

/* The fade only shows when text overflows: otherwise the scroll timeline is inactive. */

@property --truncate-fade {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@layer components {
  /* Text that's never cut: a long name, email or path breaks onto the next
     line, inside a word only when there's nowhere else to break. Use this for
     anything a person needs to read in full. */
  .wrap {
    min-width: 0;
    overflow-wrap: anywhere;
    text-wrap: pretty;
  }

  /* One line, fading at the end when cut. Only for rows that must keep a
     fixed height (a virtualized table); give the full text a title too. The padding/negative margin stops
     overflow: hidden clipping descenders and accents at tight line heights. */
  .truncate {
    min-width: 0;
    overflow: hidden;
    white-space: nowrap;
    padding-block: 0.2em;
    margin-block: -0.2em;
  }

  /* Several lines; set --truncate-lines (default 2). */
  .truncateLines {
    overflow: hidden;
    max-height: calc(var(--truncate-lines, 2) * 1lh);
  }

  @supports (animation-timeline: scroll()) {
    .truncate,
    .truncateLines {
      --truncate-to: right;
      animation: truncate-overflow linear both;
    }

    :is([dir="rtl"]) .truncate,
    :is([dir="rtl"]) .truncateLines {
      --truncate-to: left;
    }

    .truncate {
      mask-image: linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      animation-timeline: scroll(self inline);
    }

    .truncateLines {
      mask-image:
        linear-gradient(#000 0 0),
        linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      mask-size: 100% calc(100% - 1lh), 100% 1lh;
      mask-position: top, bottom;
      mask-repeat: no-repeat;
      animation-timeline: scroll(self block);
    }
  }

  /* Without scroll timelines, fall back to an ellipsis. */
  @supports not (animation-timeline: scroll()) {
    .truncate {
      text-overflow: ellipsis;
    }

    .truncateLines {
      display: -webkit-box;
      -webkit-box-orient: vertical;
      -webkit-line-clamp: var(--truncate-lines, 2);
    }
  }

  @keyframes truncate-overflow {
    from,
    to {
      --truncate-fade: 24px;
    }
  }

  /* Visually hidden, still read by screen readers. */
  .srOnly {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* Work in progress: a light band sweeps across dimmed text. --sweep-dim sets the dim. */
  .sweep {
    mask-image: linear-gradient(
      90deg,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 35%,
      #000 50%,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 65%
    );
    mask-size: 300% 100%;
    mask-repeat: no-repeat;
    animation: sweep var(--ui-dur-sweep) linear infinite;
  }

  @keyframes sweep {
    from {
      mask-position: 100% 0;
    }
    to {
      mask-position: 0 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .sweep {
      mask-image: none;
      animation: none;
    }
  }
}

@layer theme, base, components, utilities;

/* Each inline edge's mask alpha (1 solid, 0 faded). Registered so they can transition. */
@property --data-table-start {
  syntax: "<number>";
  inherits: false;
  initial-value: 1;
}

@property --data-table-end {
  syntax: "<number>";
  inherits: false;
  initial-value: 1;
}

.headLabel {
  composes: truncate from "../text/text.module.css";
}

.value {
  composes: truncate from "../text/text.module.css";
}

.loadingLabel {
  composes: sweep from "../text/text.module.css";
}

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  .root {
    --data-table-head: 40px;
    --data-table-pad: var(--ui-space-3);
    --data-table-edge: var(--ui-space-4);
    --data-table-fade: var(--ui-space-6);
    /* Mixed into the surface, not translucent, so sticky cells stay opaque. */
    --data-table-selected: light-dark(
      color-mix(in oklch, var(--ui-accent) 7%, var(--ui-surface)),
      color-mix(in oklch, var(--ui-accent) 15%, var(--ui-surface))
    );

    position: relative;
    isolation: isolate;
    display: flex;
    flex-direction: column;
    height: 440px;
    min-width: 0;
    overflow: clip;
    border-radius: var(--ui-radius-lg);
    background: var(--ui-surface);
    color: var(--ui-foreground);
    font: var(--ui-weight-regular) var(--ui-text-md) / var(--ui-leading-md) var(--ui-font-sans);
  }

  /* Drawn on top so the sticky header and column backgrounds never cover the edge. */
  .root::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 4;
    border-radius: inherit;
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-border-strong);
    pointer-events: none;
  }

  /* ---------- Scrolling ---------- */

  .viewport {
    flex: 1 1 auto;
    min-height: 0;
    overflow: auto;
    /* Inline only: stops swipe-back and rubber-banding away from the sticky column. */
    overscroll-behavior-inline: none;
    scroll-padding-block-start: calc(var(--data-table-head) + var(--ui-hairline));
    scroll-padding-inline-start: var(--data-table-sticky, 0px);
    border-radius: inherit;
    outline: none;
    scrollbar-width: thin;
    scrollbar-color: var(--ui-border-strong) transparent;

    /* Layer 1 is the edge fade; layers 2 and 3 keep classic scrollbars unmasked. */
    mask-image:
      linear-gradient(
        var(--data-table-direction, to right),
        rgb(0 0 0 / var(--data-table-start, 1)),
        black var(--data-table-fade, 32px),
        black calc(100% - var(--data-table-fade, 32px)),
        rgb(0 0 0 / var(--data-table-end, 1))
      ),
      linear-gradient(black, black),
      linear-gradient(black, black);
    mask-repeat: no-repeat;
    mask-size:
      calc(100% - var(--data-table-bar-block, 0px)) 100%,
      var(--data-table-bar-block, 0px) 100%,
      100% var(--data-table-bar-inline, 0px);
    mask-position:
      left top,
      right top,
      left bottom;
  }

  :is([dir="rtl"]) .viewport {
    --data-table-direction: to left;
    mask-position:
      right top,
      left top,
      left bottom;
  }

  .viewport[data-more-end] {
    --data-table-end: 0;
  }

  .viewport[data-more-start]:not([data-sticky-columns]) {
    --data-table-start: 0;
  }

  .viewport[data-ready] {
    transition:
      --data-table-start var(--ui-dur-fast) var(--ui-ease-color),
      --data-table-end var(--ui-dur-fast) var(--ui-ease-color);
  }

  .content {
    position: relative;
    display: flex;
    flex-direction: column;
    width: max(100%, var(--data-table-total, 0px));
    min-height: 100%;
  }

  /* ---------- Header ---------- */

  .head {
    position: sticky;
    top: 0;
    z-index: 2;
    background: var(--ui-surface);
  }

  /* The header's and each row's bottom line: a hairline drawn over the cells
     (a box-shadow on the row would sit under the opaque sticky cells). */
  .head::after,
  .row::after {
    content: "";
    position: absolute;
    inset-inline: 0;
    bottom: 0;
    height: 1px;
    box-shadow: inset 0 calc(var(--ui-hairline) * -1) 0 var(--ui-border);
    pointer-events: none;
  }

  .head::after {
    z-index: 4;
  }

  /* Over the sticky cells (z-index 1, earlier in the row), under the header. */
  .row::after {
    z-index: 1;
  }

  .headRow {
    display: grid;
    grid-template-columns: var(--data-table-template);
    height: var(--data-table-head);
  }

  .headCell {
    position: relative;
    display: flex;
    align-items: stretch;
    min-width: 0;
    border-radius: calc(var(--ui-radius-sm) / 2);
    background: var(--ui-surface);
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-sm);
    white-space: nowrap;
    outline: none;
  }

  .sortButton,
  .headStatic {
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
    display: flex;
    flex: 1 1 auto;
    align-items: center;
    gap: var(--ui-space-1);
    min-width: 0;
    padding-inline: var(--data-table-pad);
    border-radius: inherit;
    color: inherit;
    font: inherit;
    text-align: start;
  }

  .sortButton {
    margin: 0;
    border: 0;
    background: transparent;
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      color var(--ui-dur-instant) var(--ui-ease-color),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .headCell[data-align="end"] :is(.sortButton, .headStatic) {
    flex-direction: row-reverse;
    justify-content: flex-start;
    text-align: end;
  }

  .headCell:first-child :is(.sortButton, .headStatic) {
    padding-inline-start: var(--data-table-edge);
  }

  .headCell[data-sorted] {
    color: var(--ui-foreground);
  }

  .sortIcon {
    width: var(--ui-icon-sm);
    height: var(--ui-icon-sm);
    opacity: 0;
    transition: opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  .headCell[data-sorted] .sortIcon {
    opacity: 1;
  }

  @media (hover: hover) {
    .sortButton:hover {
      background: var(--ui-fill);
      color: var(--ui-foreground);
    }

    .headCell:not([data-sorted]) .sortButton:hover .sortIcon {
      opacity: 0.5;
    }
  }

  .sortButton:active {
    background: var(--ui-fill-strong);
    transition-duration: var(--ui-dur-press);
  }

  /* ---------- Resize handle ---------- */

  .resize {
    position: absolute;
    inset-block: 0;
    inset-inline-end: -12px;
    z-index: 2;
    width: 24px;
    border-radius: calc(var(--ui-radius-sm) / 2);
    outline: none;
    touch-action: none;
  }

  .resize::before {
    content: "";
    position: absolute;
    inset-block: var(--ui-space-2);
    inset-inline-start: calc(50% - var(--ui-hairline) / 2);
    width: var(--ui-hairline);
    border-radius: var(--ui-radius-full);
    background: var(--ui-border-strong);
    scale: 1 0.6;
    transition:
      scale var(--ui-dur-snap) var(--ui-ease-snap),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  @media (hover: hover) {
    .resize:hover::before {
      scale: 1;
      background: var(--ui-muted);
    }
  }

  .headCell[data-resizing] .resize::before,
  .resize:focus-visible::before {
    scale: 1;
    background: var(--ui-foreground);
  }

  .resize:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  @media (pointer: coarse) {
    .resize {
      inset-inline-end: -20px;
      width: 40px;
    }
  }

  /* ---------- Body ---------- */

  .body {
    position: relative;
    flex: 1 0 auto;
  }

  /* Sticky cells repeat --row-bg, so set row colors through it. */
  .row {
    --row-base: var(--ui-surface);
    --row-bg: var(--row-base);
    position: absolute;
    inset-inline: 0;
    display: grid;
    grid-template-columns: var(--data-table-template);
    height: var(--data-table-row);
    background: var(--row-bg);
    transition: background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .row[aria-selected="true"] {
    --row-base: var(--data-table-selected);
  }

  .root[data-focused] .row[data-active] {
    --row-bg: color-mix(in oklch, var(--row-base), var(--ui-foreground) 4%);
  }

  .cell {
    position: relative;
    display: flex;
    align-items: center;
    gap: var(--ui-space-2);
    min-width: 0;
    padding-inline: var(--data-table-pad);
    border-radius: calc(var(--ui-radius-sm) / 2);
    outline: none;
  }

  .cell:first-child {
    padding-inline-start: var(--data-table-edge);
  }

  .cell[data-align="end"] {
    justify-content: flex-end;
    font-variant-numeric: tabular-nums;
    text-align: end;
  }

  .cell:focus-visible,
  .headCell:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  /* ---------- Sticky column ---------- */

  .cell[data-sticky],
  .headCell[data-sticky] {
    position: sticky;
    inset-inline-start: 0;
    z-index: 1;
    border-radius: 0;
  }

  /* Above other headers' resize handles, which would show through as they scroll under. */
  .headCell[data-sticky] {
    z-index: 3;
  }

  .cell[data-sticky] {
    background: var(--row-bg);
    transition: background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  :is(.cell, .headCell)[data-sticky][data-col="1"] {
    inset-inline-start: var(--data-table-sticky-second, 0px);
  }

  :is(.cell, .headCell)[data-sticky-last]::after {
    content: "";
    position: absolute;
    inset-block: 0;
    inset-inline-end: 0;
    width: var(--ui-hairline);
    background: var(--ui-border);
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ui-dur-fast) var(--ui-ease-color);
  }

  .viewport[data-more-start] :is(.cell, .headCell)[data-sticky-last]::after {
    opacity: 1;
  }

  .viewport :is(.cell, .headCell)[data-sticky-last]:focus-visible::after {
    opacity: 0;
  }

  /* ---------- Selection ---------- */

  .cell.selectCell,
  .headCell.selectCell {
    padding: 0;
  }

  .check {
    flex: 1 1 auto;
    align-items: center;
    height: 100%;
    padding-inline-start: var(--data-table-edge);
  }

  /* ---------- Cells that need a look ---------- */

  .cell[data-invalid] {
    color: var(--ui-danger-text);
  }

  .issueIcon {
    --ui-icon-stroke: calc(var(--ui-icon-stroke-regular) * 16 / 14);
    width: var(--ui-icon-sm);
    height: var(--ui-icon-sm);
    margin-inline-start: auto;
  }

  .cell[data-align="end"] .issueIcon {
    order: -1;
    margin-inline-start: 0;
  }

  .footer {
    display: flex;
    flex-shrink: 0;
    align-items: flex-start;
    gap: var(--ui-space-2);
    min-height: var(--data-table-head);
    margin: 0;
    padding: calc((var(--data-table-head) - var(--ui-leading-md)) / 2) var(--data-table-edge);
    box-shadow: inset 0 var(--ui-hairline) 0 var(--ui-border);
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  .footer[data-issue] {
    color: var(--ui-foreground);
  }

  .footerIcon {
    --ui-icon-stroke: calc(var(--ui-icon-stroke-regular) * 16 / 14);
    flex-shrink: 0;
    width: var(--ui-icon-sm);
    height: var(--ui-icon-sm);
    margin-top: calc((var(--ui-leading-md) - 14px) / 2);
    color: var(--ui-danger-text);
  }

  .footerText {
    min-width: 0;
    animation: data-table-arrive var(--ui-dur-fast) var(--ui-ease-enter);
  }

  .footerWhere {
    font-weight: var(--ui-weight-medium);
  }

  /* ---------- Loading and empty ---------- */

  .placeholder {
    position: absolute;
    inset: 0;
    display: flex;
  }

  .placeholderCell {
    position: relative;
    flex: 1 1 auto;
    min-width: 0;
    animation: data-table-arrive var(--ui-dur-fast) var(--ui-ease-enter) 300ms both;
  }

  .placeholderRows {
    display: grid;
    grid-auto-rows: var(--data-table-row);
  }

  .placeholderRows span {
    box-shadow: inset 0 calc(var(--ui-hairline) * -1) 0 var(--ui-border);
  }

  .loadingLine {
    position: absolute;
    top: 0;
    inset-inline: 0;
    height: var(--data-table-row);
  }

  .loadingLabel {
    position: sticky;
    inset-inline-start: 0;
    display: inline-flex;
    align-items: center;
    height: 100%;
    padding-inline: var(--data-table-edge);
    color: var(--ui-muted);
  }

  .emptyCell {
    position: sticky;
    inset-inline-start: 0;
    display: grid;
    place-items: center;
    width: var(--data-table-viewport-width, 100%);
    max-width: 100%;
    min-height: 100%;
    overflow: auto;
  }

  .emptyText {
    margin: 0;
    padding: var(--ui-space-6) var(--ui-space-4);
    color: var(--ui-muted);
    text-align: center;
  }

  @keyframes data-table-arrive {
    from {
      opacity: 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .resize::before {
      transition: background-color var(--ui-dur-instant) var(--ui-ease-color);
    }
  }
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ComponentProps,
  type CSSProperties,
  type FocusEvent,
  type KeyboardEvent,
  type PointerEvent,
  type ReactNode,
} from "react";
import { Checkbox } from "../checkbox/checkbox";
import { Icon } from "../icons/icons";
import styles from "./data-table.module.css";

export type SortDirection = "ascending" | "descending";
export type SortState = { key: string; direction: SortDirection } | null;
type CellValue = string | number | Date | null | undefined;

export type DataTableColumn<Row> = {
  /** Unique per table; also the default row field. */
  key: string;
  header: string;
  /** Defaults to the value as text. */
  cell?: (row: Row) => ReactNode;
  /** The value sorted on. Defaults to `row[key]`; text sorts naturally. */
  value?: (row: Row) => CellValue;
  /** Px. Defaults to 160. */
  width?: number;
  /** Defaults to 72. */
  minWidth?: number;
  /** Defaults to 640. */
  maxWidth?: number;
  /** `end` for numbers (tabular figures). */
  align?: "start" | "end";
  sortable?: boolean;
  /** Custom ascending comparator. */
  compare?: (a: Row, b: Row) => number;
  /** Returns a message when the cell is invalid. */
  validate?: (row: Row) => string | null | undefined;
  /** Defaults to true. */
  resizable?: boolean;
};

type DataTableProps<Row> = Omit<ComponentProps<"div">, "children" | "onChange" | "role"> & {
  columns: DataTableColumn<Row>[];
  rows: readonly Row[];
  /** A stable id per row; selection follows it. */
  getRowId: (row: Row) => string;
  /** Names a row in its checkbox label and messages. */
  getRowLabel?: (row: Row) => string;
  /** Names the grid; prefer `aria-labelledby` with a visible heading. */
  "aria-label"?: string;
  "aria-labelledby"?: string;

  sort?: SortState;
  defaultSort?: SortState;
  onSortChange?: (sort: SortState) => void;

  columnWidths?: Record<string, number>;
  defaultColumnWidths?: Record<string, number>;
  onColumnWidthsChange?: (widths: Record<string, number>) => void;

  selectable?: boolean;
  selectedIds?: ReadonlySet<string>;
  defaultSelectedIds?: Iterable<string>;
  onSelectedIdsChange?: (ids: Set<string>) => void;

  /** Pins the first column (and checkboxes). */
  stickyFirstColumn?: boolean;
  /** Fixed row height in px, used for virtualization. Defaults to 44. */
  rowHeight?: number;
  /** Rows rendered past each edge of the visible window. Defaults to 6. */
  overscan?: number;
  loading?: boolean;
  loadingLabel?: string;
  /** Usually an EmptyState. */
  empty?: ReactNode;
  /** Locale for text sorting; fixed so server and browser sort alike. */
  locale?: string;
};

type Cell = { row: number; col: number };

const SELECT_WIDTH = 40;
const DEFAULT_WIDTH = 160;
const DEFAULT_MIN = 72;
const DEFAULT_MAX = 640;
const KEY_STEP = 16;
const KEY_STEP_LARGE = 64;
const INITIAL_ROWS = 24;

const INTERACTIVE =
  'a[href], button, input, select, textarea, [role="button"], [role="link"], [role="checkbox"], [tabindex]:not([data-cell])';

const issueKey = (rowId: string, columnKey: string) => `${rowId}\u0000${columnKey}`;

const clamp = (value: number, min: number, max: number) => Math.min(Math.max(value, min), max);

const isEmpty = (v: CellValue) =>
  v === null || v === undefined || v === "" || (typeof v === "number" && Number.isNaN(v)) || (v instanceof Date && Number.isNaN(v.getTime()));

function defaultValue<Row>(column: DataTableColumn<Row>): (row: Row) => CellValue {
  return column.value ?? ((row) => (row as Record<string, CellValue>)[column.key]);
}

function minOf<Row>(column: DataTableColumn<Row>) {
  return column.minWidth ?? DEFAULT_MIN;
}

function maxOf<Row>(column: DataTableColumn<Row>) {
  return Math.max(column.maxWidth ?? DEFAULT_MAX, minOf(column));
}

/** A keyboard-first, virtualized data grid. */
export function DataTable<Row>({
  columns,
  rows,
  getRowId,
  getRowLabel,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  sort: controlledSort,
  defaultSort = null,
  onSortChange,
  columnWidths: controlledWidths,
  defaultColumnWidths,
  onColumnWidthsChange,
  selectable = false,
  selectedIds: controlledSelected,
  defaultSelectedIds,
  onSelectedIdsChange,
  stickyFirstColumn = false,
  rowHeight = 44,
  overscan = 6,
  loading = false,
  loadingLabel = "Loading rows…",
  empty,
  locale = "en-US",
  className,
  style,
  ...props
}: DataTableProps<Row>) {
  const baseId = useId();
  const viewportRef = useRef<HTMLDivElement>(null);
  const headRef = useRef<HTMLDivElement>(null);

  /* ---------- Sorting ---------- */

  const [uncontrolledSort, setUncontrolledSort] = useState<SortState>(defaultSort);
  const sort = controlledSort === undefined ? uncontrolledSort : controlledSort;
  const sortColumn = sort ? columns.find((c) => c.key === sort.key && c.sortable) : undefined;
  const [announcement, setAnnouncement] = useState("");

  const collator = useMemo(() => new Intl.Collator(locale, { numeric: true, sensitivity: "base" }), [locale]);

  // Stable (index breaks ties); empty values go last in either direction.
  const sortedRows = useMemo(() => {
    if (!sort || !sortColumn) return rows;
    const sign = sort.direction === "ascending" ? 1 : -1;
    const compare = sortColumn.compare;
    if (compare) {
      return rows
        .map((row, index) => ({ row, index }))
        .sort((a, b) => sign * compare(a.row, b.row) || a.index - b.index)
        .map((x) => x.row);
    }
    const read = defaultValue(sortColumn);
    return rows
      .map((row, index) => {
        const raw = read(row);
        const value = raw instanceof Date ? raw.getTime() : raw;
        return { row, index, value, blank: isEmpty(raw) };
      })
      .sort((a, b) => {
        if (a.blank || b.blank) return Number(a.blank) - Number(b.blank) || a.index - b.index;
        const order =
          typeof a.value === "number" && typeof b.value === "number"
            ? a.value - b.value
            : collator.compare(String(a.value), String(b.value));
        return sign * order || a.index - b.index;
      })
      .map((x) => x.row);
  }, [rows, sort, sortColumn, collator]);

  function cycleSort(column: DataTableColumn<Row>) {
    const next: SortState =
      sort?.key !== column.key
        ? { key: column.key, direction: "ascending" }
        : sort.direction === "ascending"
          ? { key: column.key, direction: "descending" }
          : null;
    if (controlledSort === undefined) setUncontrolledSort(next);
    onSortChange?.(next);
    if (viewportRef.current) viewportRef.current.scrollTop = 0;
    setAnnouncement(next ? `Sorted by ${column.header}, ${next.direction}` : "Sort cleared");
  }

  /* ---------- Column widths ---------- */

  const [uncontrolledWidths, setUncontrolledWidths] = useState<Record<string, number>>(defaultColumnWidths ?? {});
  const widths = controlledWidths ?? uncontrolledWidths;
  const widthsRef = useRef(widths);
  useLayoutEffect(() => {
    widthsRef.current = widths;
  });

  const widthOf = (column: DataTableColumn<Row>) =>
    clamp(Math.round(widths[column.key] ?? column.width ?? DEFAULT_WIDTH), minOf(column), maxOf(column));

  const setWidth = useCallback(
    (key: string, width: number | undefined) => {
      const next = { ...widthsRef.current };
      if (width === undefined) delete next[key];
      else next[key] = width;
      widthsRef.current = next;
      if (controlledWidths === undefined) setUncontrolledWidths(next);
      onColumnWidthsChange?.(next);
    },
    [controlledWidths, onColumnWidthsChange],
  );

  /* ---------- Selection ---------- */

  const [uncontrolledSelected, setUncontrolledSelected] = useState<ReadonlySet<string>>(
    () => new Set(defaultSelectedIds ?? []),
  );
  const selected = controlledSelected ?? uncontrolledSelected;
  const anchorRef = useRef<string | null>(null);
  const shiftRef = useRef(false);

  const rowIds = useMemo(() => sortedRows.map(getRowId), [sortedRows, getRowId]);
  const selectedCount = useMemo(() => rowIds.reduce((n, id) => n + (selected.has(id) ? 1 : 0), 0), [rowIds, selected]);
  const allSelected = rowIds.length > 0 && selectedCount === rowIds.length;
  const someSelected = selectedCount > 0 && !allSelected;

  function commitSelection(next: Set<string>) {
    if (controlledSelected === undefined) setUncontrolledSelected(next);
    onSelectedIdsChange?.(next);
  }

  function toggleAll() {
    const next = new Set(selected);
    for (const id of rowIds) {
      if (allSelected) next.delete(id);
      else next.add(id);
    }
    commitSelection(next);
  }

  function toggleRow(index: number, range: boolean) {
    const id = rowIds[index];
    const on = !selected.has(id);
    const next = new Set(selected);
    const anchor = anchorRef.current === null ? -1 : rowIds.indexOf(anchorRef.current);
    if (range && anchor !== -1) {
      const [from, to] = anchor < index ? [anchor, index] : [index, anchor];
      for (let i = from; i <= to; i++) {
        if (on) next.add(rowIds[i]);
        else next.delete(rowIds[i]);
      }
    } else if (on) next.add(id);
    else next.delete(id);
    anchorRef.current = id;
    commitSelection(next);
  }

  /* ---------- Validation ---------- */

  const issues = useMemo(() => {
    const map = new Map<string, string>();
    for (const column of columns) {
      if (!column.validate) continue;
      for (const row of rows) {
        const message = column.validate(row);
        if (message) map.set(issueKey(getRowId(row), column.key), message);
      }
    }
    return map;
  }, [rows, columns, getRowId]);

  /* ---------- Layout ---------- */

  const offset = selectable ? 1 : 0;
  const colCount = columns.length + offset;
  // Only pin while the pinned part takes at most 60% of the box.
  const [viewWidth, setViewWidth] = useState(Infinity);
  const columnWidths = columns.map(widthOf);
  // In a narrow box (a phone), a pinned first column gives up width, down to
  // its minimum, so it can stay pinned: the names stay in view while the
  // other columns scroll under them. A width someone dragged is kept.
  if (stickyFirstColumn && columns.length > 0 && widths[columns[0].key] === undefined) {
    const room = Math.floor(viewWidth * 0.6) - (selectable ? SELECT_WIDTH : 0);
    if (room < columnWidths[0]) columnWidths[0] = Math.max(minOf(columns[0]), room);
  }
  const template = [...(selectable ? [`${SELECT_WIDTH}px`] : []), ...columnWidths.map((w) => `${w}px`), "minmax(0, 1fr)"].join(" ");
  const total = (selectable ? SELECT_WIDTH : 0) + columnWidths.reduce((a, b) => a + b, 0);
  const pinnedWidth = columns.length > 0 ? (selectable ? SELECT_WIDTH : 0) + columnWidths[0] : 0;
  const stickyCount = stickyFirstColumn && columns.length > 0 && pinnedWidth <= viewWidth * 0.6 ? offset + 1 : 0;
  const stickyWidth = stickyCount === 0 ? 0 : pinnedWidth;

  /* ---------- Virtual window ---------- */

  const [range, setRange] = useState({ start: 0, end: INITIAL_ROWS });
  const [bodyHeight, setBodyHeight] = useState(INITIAL_ROWS * rowHeight);
  const rowCount = sortedRows.length;
  const showRows = rowCount > 0;
  const showLoading = loading && !showRows;
  const showEmpty = !loading && !showRows;

  const measure = useCallback(() => {
    const viewport = viewportRef.current;
    const head = headRef.current;
    if (!viewport || !head) return;
    const visible = Math.max(0, viewport.clientHeight - head.offsetHeight);
    const top = viewport.scrollTop;
    const start = Math.max(0, Math.floor(top / rowHeight) - overscan);
    const end = Math.ceil((top + visible) / rowHeight) + overscan;
    setRange((r) => (r.start === start && r.end === end ? r : { start, end }));
    setBodyHeight(visible);

    // scrollLeft is negative in RTL, so use its magnitude.
    const max = viewport.scrollWidth - viewport.clientWidth;
    const inline = Math.abs(viewport.scrollLeft);
    viewport.toggleAttribute("data-more-start", inline > 1);
    viewport.toggleAttribute("data-more-end", max - inline > 1);
    viewport.style.setProperty("--data-table-bar-block", `${Math.max(0, viewport.offsetWidth - viewport.clientWidth)}px`);
    viewport.style.setProperty("--data-table-bar-inline", `${Math.max(0, viewport.offsetHeight - viewport.clientHeight)}px`);
    viewport.style.setProperty("--data-table-viewport-width", `${viewport.clientWidth}px`);
    setViewWidth(viewport.clientWidth);
  }, [rowHeight, overscan]);

  useLayoutEffect(() => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    measure();
      const frame = requestAnimationFrame(() => viewport.setAttribute("data-ready", ""));
    const observer = new ResizeObserver(measure);
    observer.observe(viewport);
    viewport.addEventListener("scroll", measure, { passive: true });
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      viewport.removeEventListener("scroll", measure);
    };
  }, [measure]);

  // Widths and row count change the scroll range without a resize.
  useLayoutEffect(() => measure(), [measure, total, rowCount]);

  /* ---------- Active cell and focus ---------- */

  const [active, setActive] = useState<Cell>({ row: 0, col: 0 });
  const [focused, setFocused] = useState(false);
  const focusPending = useRef(false);
  const lastRow = showRows ? rowCount : 0;
  const current: Cell = { row: clamp(active.row, 0, lastRow), col: clamp(active.col, 0, colCount - 1) };

  const cellId = (cell: Cell) => `${baseId}-${cell.row}-${cell.col}`;

  function moveTo(cell: Cell) {
    focusPending.current = true;
    setActive({ row: clamp(cell.row, 0, lastRow), col: clamp(cell.col, 0, colCount - 1) });
  }

  useLayoutEffect(() => {
    if (!focusPending.current) return;
    focusPending.current = false;
    const el = document.getElementById(cellId(current));
    if (!el) return;
    el.focus({ preventScroll: true });
    el.scrollIntoView({ block: "nearest", inline: "nearest" });
  });

  // The grid is one tab stop. Runs every render: cell content can change.
  useLayoutEffect(() => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    for (const el of viewport.querySelectorAll<HTMLElement>(`[data-cell] :is(${INTERACTIVE})`)) {
      if (el.dataset.resize === undefined && el.tabIndex !== -1) el.tabIndex = -1;
    }
  });

  function cellFrom(target: EventTarget | null) {
    const el = (target as HTMLElement | null)?.closest<HTMLElement>("[data-cell]");
    if (!el || !viewportRef.current?.contains(el)) return null;
    return { el, cell: { row: Number(el.dataset.row), col: Number(el.dataset.col) } };
  }

  function handleFocus(event: FocusEvent<HTMLDivElement>) {
    setFocused(true);
    const hit = cellFrom(event.target);
    if (hit && (hit.cell.row !== current.row || hit.cell.col !== current.col)) setActive(hit.cell);
  }

  function handleBlur(event: FocusEvent<HTMLDivElement>) {
    if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setFocused(false);
  }

  function activate(el: HTMLElement) {
    shiftRef.current = false;
    const target = el.querySelector<HTMLElement>(INTERACTIVE);
    target?.click();
  }

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    const hit = cellFrom(event.target);
    if (!hit || event.altKey) return;
    const { el, cell } = hit;
    const inside = event.target !== el;
    const mod = event.ctrlKey || event.metaKey;

    if (inside) {
      // Focus is inside the cell: Space and Enter belong to the control.
      if (event.key === "Escape") {
        event.preventDefault();
        el.focus();
        return;
      }
      if (event.key === " " || event.key === "Enter") return;
    }

    const rtl = getComputedStyle(event.currentTarget).direction === "rtl";
    const page = Math.max(1, Math.floor(bodyHeight / rowHeight) - 1);
    let next: Cell | null = null;

    switch (event.key) {
      case "ArrowDown":
        next = { row: cell.row + 1, col: cell.col };
        break;
      case "ArrowUp":
        next = { row: cell.row - 1, col: cell.col };
        break;
      case "ArrowRight":
        next = { row: cell.row, col: cell.col + (rtl ? -1 : 1) };
        break;
      case "ArrowLeft":
        next = { row: cell.row, col: cell.col + (rtl ? 1 : -1) };
        break;
      case "Home":
        next = mod ? { row: 0, col: 0 } : { row: cell.row, col: 0 };
        break;
      case "End":
        next = mod ? { row: lastRow, col: colCount - 1 } : { row: cell.row, col: colCount - 1 };
        break;
      case "PageDown":
        next = { row: cell.row === 0 ? Math.min(page, lastRow) : cell.row + page, col: cell.col };
        break;
      case "PageUp":
        next = { row: cell.row <= 1 ? 0 : Math.max(1, cell.row - page), col: cell.col };
        break;
      case "Enter":
        event.preventDefault();
        activate(el);
        return;
      case " ":
        event.preventDefault();
        if (selectable && cell.row > 0 && (cell.col === 0 || event.shiftKey)) toggleRow(cell.row - 1, false);
        else if (selectable && cell.row === 0 && cell.col === 0) toggleAll();
        else if (cell.row === 0) activate(el);
        return;
      case "a":
      case "A":
        if (mod && selectable && showRows) {
          event.preventDefault();
          if (!allSelected) toggleAll();
        }
        return;
      default:
        return;
    }
    event.preventDefault();
    if (next.row === 0 && cell.row !== 0 && event.key !== "ArrowUp" && viewportRef.current) {
      viewportRef.current.scrollTop = 0;
    }
    moveTo(next);
  }

  /* ---------- Rows to render ---------- */

  const first = Math.min(range.start, rowCount);
  const last = Math.min(range.end, rowCount);
  const indices: number[] = [];
  // Keep the active row rendered when scrolled away so focus is never unmounted.
  if (showRows && current.row > 0 && current.row - 1 < first) indices.push(current.row - 1);
  for (let i = first; i < last; i++) indices.push(i);
  if (showRows && current.row > 0 && current.row - 1 >= last) indices.push(current.row - 1);

  const activeId = showRows && current.row > 0 ? rowIds[current.row - 1] : null;
  const activeColumn = current.col >= offset ? columns[current.col - offset] : undefined;
  const activeIssue = activeId && activeColumn ? issues.get(issueKey(activeId, activeColumn.key)) : undefined;
  const activeRowLabel =
    activeIssue && getRowLabel ? getRowLabel(sortedRows[current.row - 1]) : `Row ${current.row}`;

  const placeholderRows = Math.max(1, Math.ceil(bodyHeight / rowHeight));

  const vars = {
    "--data-table-template": template,
    "--data-table-total": `${total}px`,
    "--data-table-row": `${rowHeight}px`,
    "--data-table-sticky": `${stickyWidth}px`,
    "--data-table-sticky-second": `${selectable ? SELECT_WIDTH : 0}px`,
  } as CSSProperties;

  const stickyAttrs = (col: number) =>
    col < stickyCount ? { "data-sticky": "", "data-sticky-last": col === stickyCount - 1 ? "" : undefined } : {};

  return (
    <div
      className={className ? `${styles.root} ${className}` : styles.root}
      style={{ ...vars, ...style }}
      data-focused={focused || undefined}
      {...props}
    >
      <div
        ref={viewportRef}
        role="grid"
        className={styles.viewport}
        aria-label={ariaLabel}
        aria-labelledby={ariaLabelledBy}
        aria-rowcount={showRows ? rowCount + 1 : showLoading || showEmpty ? 2 : 1}
        aria-colcount={colCount}
        aria-multiselectable={selectable || undefined}
        aria-busy={loading || undefined}
        data-sticky-columns={stickyCount > 0 || undefined}
        onFocus={handleFocus}
        onBlur={handleBlur}
        onKeyDown={handleKeyDown}
      >
        <div className={styles.content} role="presentation">
          <div ref={headRef} role="rowgroup" className={styles.head}>
            <div role="row" aria-rowindex={1} className={styles.headRow}>
              {selectable && (
                <div
                  id={cellId({ row: 0, col: 0 })}
                  role="columnheader"
                  className={`${styles.headCell} ${styles.selectCell}`}
                  tabIndex={current.row === 0 && current.col === 0 ? 0 : -1}
                  data-cell=""
                  data-row={0}
                  data-col={0}
                  {...stickyAttrs(0)}
                >
                  <Checkbox
                    className={styles.check}
                    aria-label="Select all rows"
                    tabIndex={-1}
                    checked={allSelected}
                    indeterminate={someSelected}
                    disabled={!showRows}
                    onCheckedChange={toggleAll}
                  />
                </div>
              )}
              {columns.map((column, i) => {
                const col = i + offset;
                return (
                  <HeaderCell
                    key={column.key}
                    id={cellId({ row: 0, col })}
                    column={column}
                    col={col}
                    width={columnWidths[i]}
                    sort={sort?.key === column.key && sortColumn ? sort.direction : null}
                    isActive={current.row === 0 && current.col === col}
                    onSort={() => cycleSort(column)}
                    onResize={(w) => setWidth(column.key, w)}
                    sticky={stickyAttrs(col)}
                  />
                );
              })}
            </div>
          </div>

          <div
            role="rowgroup"
            className={styles.body}
            style={showRows ? { height: rowCount * rowHeight } : undefined}
          >
            {indices.map((index) => {
              const row = sortedRows[index];
              const id = rowIds[index];
              const isSelected = selected.has(id);
              const rowLabel = getRowLabel?.(row) ?? `row ${index + 1}`;
              return (
                <div
                  key={id}
                  role="row"
                  aria-rowindex={index + 2}
                  aria-selected={selectable ? isSelected : undefined}
                  className={styles.row}
                  style={{ top: index * rowHeight }}
                  data-active={current.row === index + 1 || undefined}
                >
                  {selectable && (
                    <div
                      id={cellId({ row: index + 1, col: 0 })}
                      role="gridcell"
                      className={`${styles.cell} ${styles.selectCell}`}
                      tabIndex={current.row === index + 1 && current.col === 0 ? 0 : -1}
                      data-cell=""
                      data-row={index + 1}
                      data-col={0}
                      {...stickyAttrs(0)}
                      onPointerDown={(e) => {
                        shiftRef.current = e.shiftKey;
                        // Prevents text selection on shift-click.
                        if (e.shiftKey) e.preventDefault();
                      }}
                    >
                      <Checkbox
                        className={styles.check}
                        aria-label={`Select ${rowLabel}`}
                        tabIndex={-1}
                        checked={isSelected}
                        onCheckedChange={() => {
                          toggleRow(index, shiftRef.current);
                          shiftRef.current = false;
                        }}
                      />
                    </div>
                  )}
                  {columns.map((column, i) => {
                    const col = i + offset;
                    const issue = column.validate ? issues.get(issueKey(id, column.key)) : undefined;
                    const messageId = issue ? `${cellId({ row: index + 1, col })}-issue` : undefined;
                    return (
                      <div
                        key={column.key}
                        id={cellId({ row: index + 1, col })}
                        role="gridcell"
                        className={styles.cell}
                        tabIndex={current.row === index + 1 && current.col === col ? 0 : -1}
                        data-cell=""
                        data-row={index + 1}
                        data-col={col}
                        data-align={column.align ?? "start"}
                        data-invalid={issue ? "" : undefined}
                        aria-invalid={issue ? true : undefined}
                        aria-describedby={messageId}
                        {...stickyAttrs(col)}
                      >
                        <CellValue column={column} row={row} />
                        {issue && (
                          <>
                            <Icon name="alert" className={styles.issueIcon} />
                            <span id={messageId} className={styles.srOnly}>
                              {issue}
                            </span>
                          </>
                        )}
                      </div>
                    );
                  })}
                </div>
              );
            })}

            {showLoading && (
              <div role="row" aria-rowindex={2} className={styles.placeholder}>
                <div role="gridcell" aria-colspan={colCount} className={styles.placeholderCell}>
                  <div className={styles.placeholderRows} aria-hidden="true">
                    {Array.from({ length: placeholderRows }, (_, i) => (
                      <span key={i} />
                    ))}
                  </div>
                  <div className={styles.loadingLine}>
                    <span className={styles.loadingLabel}>{loadingLabel}</span>
                  </div>
                </div>
              </div>
            )}

            {showEmpty && (
              <div role="row" aria-rowindex={2} className={styles.placeholder}>
                <div role="gridcell" aria-colspan={colCount} className={styles.emptyCell}>
                  {empty ?? <p className={styles.emptyText}>Nothing here yet.</p>}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      {issues.size > 0 && showRows && (
        <p className={styles.footer} data-issue={activeIssue && focused ? "" : undefined}>
          <Icon name="alert" className={styles.footerIcon} />
          {activeIssue && focused ? (
            <span key={`${activeId}-${activeColumn?.key}`} className={styles.footerText}>
              <span className={styles.footerWhere}>
                {activeRowLabel}, {activeColumn?.header}
              </span>{" "}
              {activeIssue}
            </span>
          ) : (
            <span key="summary" className={styles.footerText}>
              {issues.size === 1 ? "1 cell needs a look" : `${issues.size} cells need a look`}
            </span>
          )}
        </p>
      )}

      <span className={styles.srOnly} role="status">
        {announcement}
      </span>
    </div>
  );
}

/** A cell stays one line, because rows are a fixed height for virtualizing.
 *  When its text is cut, the full value is its title, so it's never lost. */
function CellValue<Row>({ column, row }: { column: DataTableColumn<Row>; row: Row }) {
  const content = renderCell(column, row);
  return (
    <span
      className={styles.value}
      title={typeof content === "string" ? content : undefined}
    >
      {content}
    </span>
  );
}

function renderCell<Row>(column: DataTableColumn<Row>, row: Row): ReactNode {
  if (column.cell) return column.cell(row);
  const value = defaultValue(column)(row);
  if (isEmpty(value)) return null;
  return value instanceof Date ? value.toISOString().slice(0, 10) : String(value);
}

/* ---------- Header cell: sort button and resize handle ---------- */

type HeaderCellProps<Row> = {
  id: string;
  column: DataTableColumn<Row>;
  col: number;
  width: number;
  sort: SortDirection | null;
  isActive: boolean;
  onSort: () => void;
  onResize: (width: number | undefined) => void;
  sticky: Record<string, string | undefined>;
};

function HeaderCell<Row>({ id, column, col, width, sort, isActive, onSort, onResize, sticky }: HeaderCellProps<Row>) {
  const resizable = column.resizable ?? true;
  const min = minOf(column);
  const max = maxOf(column);
  const drag = useRef<{ x: number; width: number; pointer: number } | null>(null);
  const [resizing, setResizing] = useState(false);

  // Keep the direction while the arrow fades out.
  const [arrow, setArrow] = useState<"arrow-up" | "arrow-down">(sort === "descending" ? "arrow-down" : "arrow-up");
  const wanted = sort === "descending" ? "arrow-down" : sort === "ascending" ? "arrow-up" : null;
  if (wanted && wanted !== arrow) setArrow(wanted);
  useEffect(() => {
    if (sort || arrow === "arrow-up") return;
    const timer = window.setTimeout(() => setArrow("arrow-up"), 240);
    return () => window.clearTimeout(timer);
  }, [sort, arrow]);

  const rtl = (el: Element) => getComputedStyle(el).direction === "rtl";

  function handlePointerDown(event: PointerEvent<HTMLSpanElement>) {
    if (event.button !== 0) return;
    event.preventDefault();
    event.currentTarget.setPointerCapture(event.pointerId);
    drag.current = { x: event.clientX, width, pointer: event.pointerId };
    setResizing(true);
  }

  function handlePointerMove(event: PointerEvent<HTMLSpanElement>) {
    const d = drag.current;
    if (!d || d.pointer !== event.pointerId) return;
    const delta = (event.clientX - d.x) * (rtl(event.currentTarget) ? -1 : 1);
    onResize(clamp(Math.round(d.width + delta), min, max));
  }

  function endDrag(event: PointerEvent<HTMLSpanElement>) {
    if (drag.current?.pointer !== event.pointerId) return;
    drag.current = null;
    setResizing(false);
  }

  useEffect(() => {
    if (!resizing) return;
    const onKey = (event: globalThis.KeyboardEvent) => {
      if (event.key !== "Escape" || !drag.current) return;
      onResize(drag.current.width);
      drag.current = null;
      setResizing(false);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [resizing, onResize]);

  function handleKeyDown(event: KeyboardEvent<HTMLSpanElement>) {
    const cell = event.currentTarget.closest<HTMLElement>("[data-cell]");
    const step = event.shiftKey ? KEY_STEP_LARGE : KEY_STEP;
    const grow = rtl(event.currentTarget) ? "ArrowLeft" : "ArrowRight";
    const shrink = rtl(event.currentTarget) ? "ArrowRight" : "ArrowLeft";
    let next: number | null = null;
    if (event.key === grow) next = width + step;
    else if (event.key === shrink) next = width - step;
    else if (event.key === "Home") next = min;
    else if (event.key === "End") next = max;
    else if (event.key === "Escape" || event.key === "Enter") {
      event.preventDefault();
      event.stopPropagation();
      cell?.focus();
      return;
    } else if (event.key === "ArrowUp" || event.key === "ArrowDown") {
      // Keep the grid from moving focus away mid-adjustment.
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    if (next === null) return;
    event.preventDefault();
    event.stopPropagation();
    onResize(clamp(next, min, max));
  }

  const label = (
    <>
      <span className={styles.headLabel} title={typeof column.header === "string" ? column.header : undefined}>
        {column.header}
      </span>
      {column.sortable && <Icon name={arrow} className={styles.sortIcon} />}
    </>
  );

  return (
    <div
      id={id}
      role="columnheader"
      className={styles.headCell}
      tabIndex={isActive ? 0 : -1}
      aria-sort={sort ?? undefined}
      data-cell=""
      data-row={0}
      data-col={col}
      data-align={column.align ?? "start"}
      data-sorted={sort ? "" : undefined}
      data-resizing={resizing || undefined}
      {...sticky}
    >
      {column.sortable ? (
        <button type="button" tabIndex={-1} className={styles.sortButton} onClick={onSort}>
          {label}
        </button>
      ) : (
        <span className={styles.headStatic}>{label}</span>
      )}
      {resizable && (
        <span
          role="separator"
          aria-orientation="vertical"
          aria-label={`Resize ${column.header} column`}
          aria-valuenow={width}
          aria-valuemin={min}
          aria-valuemax={max}
          aria-valuetext={`${width} pixels`}
          // Tabbable only from its own active header cell; the grid stays one stop.
          tabIndex={isActive ? 0 : -1}
          data-resize=""
          className={styles.resize}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={endDrag}
          onPointerCancel={endDrag}
          onLostPointerCapture={endDrag}
          onDoubleClick={() => onResize(undefined)}
          onKeyDown={handleKeyDown}
        />
      )}
    </div>
  );
}
